const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const DEFAULT_TH = (cfg.thresholds && cfg.thresholds.default) || {};
const MACHINES = $('Machines ophalen').all().map(x=>x.json);
const TH = DEFAULT_TH;
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const latest = $input.all().map(i=>i.json);
const rows=MACHINES.map(m=>({...latest.find(r=>r.machine===m.machine),machine:m.machine,thresholds:m.thresholds}));          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= ({...DEFAULT_TH,...(r.thresholds||{})}.offline_min??10));
const label = m => (m||'?');

const t = hhmm(); const out=[];
const stt=(v,w,h)=>isNaN(v)?'ok':(v>h?'high':(v>w?'warn':'ok'));
for(const d of online){
  const T={...DEFAULT_TH,...(d.thresholds||{})};
  const OFFLINE_MIN=T.offline_min??10,UPD_MANY=T.updates_many??20,BAT_MIN=T.bat_min??15,DISK_WARN=T.disk_warn??80,DISK_ALARM=T.disk_alarm??90,TEMP_ALARM=T.temp_alarm??90,DISK_FORECAST_DAYS=T.disk_forecast_days??14,RAM_ALARM=T.ram_alarm??85,SWAP_ALARM=T.swap_alarm??50;
  const cpu=num(d.cpu),mem=num(d.mem),disk=num(d.disk),temp=num(d.temp),load1=num(d.load1),upd=num(d.updates);
  const bat=num(d.battery),plug=d.bat_plugged;
  const cores=asArr(d.cores),ct=asArr(d.core_temps);
  const R=[];
  R.push({label:'CPU',value:isNaN(cpu)?'—':Math.round(cpu)+'%',pct:isNaN(cpu)?null:cpu,status:stt(cpu,75,90)});
  R.push({label:'RAM',value:isNaN(mem)?'—':Math.round(mem)+'%',pct:isNaN(mem)?null:mem,status:stt(mem,75,90)});
  R.push({label:'SCHIJF',value:isNaN(disk)?'—':Math.round(disk)+'%',pct:isNaN(disk)?null:disk,status:stt(disk,DISK_WARN,DISK_ALARM)});
  R.push({label:'TEMP',value:isNaN(temp)?'—':Math.round(temp)+'\u00b0C',status:stt(temp,TEMP_ALARM-10,TEMP_ALARM)});
  R.push({label:'LOAD',value:isNaN(load1)?'—':load1.toFixed(2),status:'ok'});
  R.push({label:'UPDATES',value:isNaN(upd)?'—':(upd<=0?'up-to-date':upd+' klaar'),status:isNaN(upd)?'ok':(upd>UPD_MANY?'high':(upd>0?'warn':'ok'))});
  if(!isNaN(bat)){const s=plug===true?'aan stroom':(plug===false?'op accu':'');let bs='ok';if(plug===false&&bat<BAT_MIN)bs='high';else if(plug===false&&bat<40)bs='warn';R.push({label:'ACCU',value:Math.round(bat)+'%'+(s?' \u00b7 '+s:''),status:bs});}
  if(cores&&cores.length)R.push({label:'CORE LOAD',value:cores.map(x=>Math.round(Number(x))).join('\u00b7')+'%',status:'ok'});
  if(ct&&ct.length)R.push({label:'CORE TEMP',value:ct.join('\u00b7')+'\u00b0C',status:stt(Math.max.apply(null,ct.map(Number)),TEMP_ALARM-10,TEMP_ALARM)});
  const anyHigh=R.some(r=>r.status==='high'); const sym=anyHigh?'\u25B2':'\u2713';
  out.push({json:{caption:sym+' Rapport \u2014 '+label(d.machine)+' \u00b7 '+t,
    spec:{title:sym+' Health report \u2014 '+label(d.machine),subtitle:t,state:anyHigh?'alert':'ok',rows:R,
      footer:'SysDash \u00b7 rapport \u00b7 '+online.length+' online \u00b7 '+t}}});
}
return out;
